std::uint64_t range_bytes(const std::vector<Range>&rs){std::uint64_t n=0;for(const auto&r:rs)if(r.end>r.start)n+=r.end-r.start;return n;}
bool has_unpack_artifact(const RuntimeReport&r,std::uint64_t uid){for(const auto&a:r.artifacts)if(a.process_uid==uid&&(a.kind=="unpacked_pe"||a.kind=="unpack_diagnostic"))return true;return false;}
bool executable_protect(DWORD p){switch(p&0xffu){case PAGE_EXECUTE:case PAGE_EXECUTE_READ:case PAGE_EXECUTE_READWRITE:case PAGE_EXECUTE_WRITECOPY:return true;default:return false;}}
std::string protect_hex(DWORD p){return "0x"+hex_u64(p);}
void emit_memory_event(RuntimeReport&r,LARGE_INTEGER st,LARGE_INTEGER fq,const PState&s,TimelineKind kind,const std::string&subject,std::map<std::string,std::string>fields);
bool image_geometry_overlap(const PState&s,const Range&r){const auto b=reinterpret_cast<std::uintptr_t>(s.base),e=b+s.packed_pe.image_size;return s.packed_pe.valid&&r.start<e&&r.end>b;}
bool image_geometry_overlap(const PState&s,std::uintptr_t start,std::uint64_t size){if(!s.packed_pe.valid||!s.base||!size||start>std::numeric_limits<std::uintptr_t>::max()-size)return false;const auto b=reinterpret_cast<std::uintptr_t>(s.base),e=b+s.packed_pe.image_size;return start<e&&start+static_cast<std::uintptr_t>(size)>b;}
bool active_original_image_overlap(const PState&s,std::uintptr_t start,std::uint64_t size){return !s.original_image_unmapped&&image_geometry_overlap(s,start,size);}
std::string image_relation(const PState&s,const Range&r){return image_geometry_overlap(s,r)?(s.original_image_unmapped?"replacement_at_original_base":"original_image"):"non_image";}
std::string image_relation(const PState&s,std::uintptr_t start,std::uint64_t size){return image_geometry_overlap(s,start,size)?(s.original_image_unmapped?"replacement_at_original_base":"original_image"):"non_image";}
