void correlate_iat_with_resolver(IatCandidate&iat,const PState&s){
    if(s.resolver_observations.empty())return;
    constexpr std::size_t storage_cap=512;
    for(const auto&p:iat.observed_export_pointers){const ResolverObservation*best=nullptr;std::size_t best_index=0;int bestscore=-1;
        for(std::size_t oi=0;oi<s.resolver_observations.size();++oi){const auto&o=s.resolver_observations[oi];if(!o.success||!o.resolved_va||o.resolved_va!=p.resolved_va)continue;int score=1;if(!o.requested_module.empty())score+=10;if(o.by_ordinal||!o.requested_name.empty())score+=10;if(o.caller_return_rva!=0xffffffffu)score+=2;if(score>bestscore){bestscore=score;best=&o;best_index=oi;}}
        if(!best)continue;const bool in_iat=iat.mapped_count&&p.rva>=iat.start_rva&&p.rva<iat.end_rva;if(in_iat)++iat.resolver_storage_in_iat_candidate;else ++iat.resolver_storage_outside_iat_candidate;if(iat.resolver_storage_matches.size()<storage_cap)iat.resolver_storage_matches.push_back({best_index,p.rva,p.resolved_va,in_iat});else iat.resolver_storage_matches_truncated=true;
    }
    if(!iat.mapped_count)return;
    for(auto&g:iat.groups){std::map<std::string,std::pair<std::string,std::size_t>> libs;std::size_t correlated=0;
        for(auto&e:g.entries){const ResolverObservation*best=nullptr;int bestscore=-1;for(const auto&o:s.resolver_observations){if(!o.success||!o.resolved_va||o.resolved_va!=e.resolved_va)continue;int score=1;const auto req_lib=normalize_module_leaf(o.requested_module),cur_lib=normalize_module_leaf(e.func.libName);if(!req_lib.empty()&&req_lib==cur_lib)score+=100;if(!o.by_ordinal&&!o.requested_name.empty()&&o.requested_name==e.func.funcName)score+=50;if(score>bestscore){bestscore=score;best=&o;}}
            if(!best)continue;e.resolver_correlated=true;++correlated;++iat.resolver_matched_entries;std::string exact=module_leaf(best->requested_module),norm=normalize_module_leaf(exact);if(!norm.empty()){auto&x=libs[norm];if(x.first.empty())x.first=exact;++x.second;}e.func.libName=exact.empty()?e.func.libName:exact;e.func.isByOrdinal=best->by_ordinal;if(best->by_ordinal){e.func.funcName.clear();e.func.funcOrdinal=best->ordinal;}else if(!best->requested_name.empty()){e.func.funcName=best->requested_name;e.func.funcOrdinal=peconv::INVALID_ORD_VALUE;}}
        if(!correlated)continue;std::string chosen;std::size_t chosen_count=0;for(const auto&kv:libs)if(kv.second.second>chosen_count){chosen=kv.second.first;chosen_count=kv.second.second;}if(chosen_count==g.entries.size()){g.lib_name=chosen;g.library_identity_fallback=false;++iat.resolver_identity_groups;}else if(libs.size()>1)++iat.resolver_identity_conflicts;
    }
}
std::string pe_section_for_rva(const PeInfo&pe,std::uint32_t rva){for(const auto&sec:pe.sections){const auto n=std::max(sec.vsize,sec.raw_size);if(rva>=sec.rva&&std::uint64_t(rva)-sec.rva<n)return sec.name;}return{};}
