        std::uintptr_t start=0,end=0;
        try{start=static_cast<std::uintptr_t>(std::stoull(range.substr(0,dash),nullptr,16));end=static_cast<std::uintptr_t>(std::stoull(range.substr(dash+1),nullptr,16));}catch(...){why="vdso_range_parse_failed";return false;}
